#!/bin/bash
H="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; S="${S:-/tmp/pb}"; mkdir -p "$S"
for n in "$@"; do echo "== $n"; grep -a -A14 "own crossings" $S/$n.txt | grep -a "own crossings\|striking \|pose itself\|by part" | sed -E 's/ +/ /g; s/, as seen//; s/: seconds of each, and the share of that time//' | cut -c1-260; grep -a "gives way to his own sword\|met softly" $S/$n.txt | cut -c1-200; grep -a -A9 "what he holds trembles" $S/$n.txt | grep -a "in all" | sed -E 's/ +/ /g' | cut -c1-110; grep -a "blows met, by where" $S/$n.txt | cut -c1-300; grep -a "a blade in its own body" $S/$n.txt | cut -c1-140; grep -a -c "Exception" $S/$n.txt; done
